#include "binx/cli/dependency_output.hpp"
#include <sstream>
namespace binx {
namespace {std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"')o+="\\\"";else if(c=='\\')o+="\\\\";
else o+=c;}return o;}}
std::string format_dependencies(const std::vector<Dependency>&v,bool json){std::ostringstream o;if(json){o<<"{\"schema_version\":5,\"dependencies\":[";for(std::size_t i=0;i<v.size();++i){if(i)o<<",";o<<"{\"name\":\""<<esc(v[i].name)<<"\",\"kind\":\""<<dependency_kind_name(v[i].kind)<<"\",\"weak\":"<<(v[i].weak?"true":"false")<<",\"reexport\":"<<(v[i].reexport?"true":"false")<<"}";}o<<"]}\n";return o.str();}o<<"DEPENDENCIES\n";for(const auto&d:v)o<<"  "<<d.name<<" ["<<dependency_kind_name(d.kind)<<(d.weak?", weak":"")<<(d.reexport?", reexport":"")<<"]\n";return o.str();}
std::string format_dependency_graph(const DependencyGraph&g,bool json){std::ostringstream o;if(json){o<<"{\"schema_version\":5,\"nodes\":[";for(std::size_t i=0;i<g.nodes.size();++i){if(i)o<<",";auto&n=g.nodes[i];o<<"{\"id\":"<<n.id<<",\"path\":\""<<esc(n.path.string())<<"\",\"format\":\""<<format_name(n.format)<<"\",\"architecture\":\""<<architecture_name(n.architecture)<<"\",\"resolved\":"<<(n.resolved?"true":"false")<<"}";}o<<"],\"edges\":[";for(std::size_t i=0;i<g.edges.size();++i){if(i)o<<",";auto&e=g.edges[i];o<<"{\"from\":"<<e.from<<",\"to\":"<<e.to<<",\"name\":\""<<esc(e.dependency.name)<<"\",\"kind\":\""<<dependency_kind_name(e.dependency.kind)<<"\"}";}o<<"],\"unresolved\":[";for(std::size_t i=0;i<g.unresolved.size();++i){if(i)o<<",";o<<"\""<<esc(g.unresolved[i])<<"\"";}o<<"],\"cycles\":"<<g.cycles.size()<<"}\n";return o.str();}o<<"DEPENDENCY GRAPH\n\n";for(const auto&n:g.nodes)o<<"  ["<<n.id<<"] "<<n.path.string()<<"  "<<format_name(n.format)<<"  "<<(n.resolved?"resolved":"unresolved")<<"\n";o<<"\nEDGES\n";for(const auto&e:g.edges)o<<"  ["<<e.from<<"] --"<<dependency_kind_name(e.dependency.kind)<<"--> ["<<e.to<<"] "<<e.dependency.name<<"\n";o<<"\nUNRESOLVED\n";for(const auto&s:g.unresolved)o<<"  "<<s<<"\n";o<<"\nCYCLES: "<<g.cycles.size()<<"\n";return o.str();}
}
